// Kept events: an application keeping the events it publishes so (Go's
// ClientsConfig.Kept) says in its hello where its log is and offers
// KeptEvents; a client following them lists KeptEvents among its welcome's
// uses and calls Follow with its cursor, getting the events kept after it,
// then each as it is kept, as a typed stream. app.md, comms-chat-team's #1.

import { RemoteError } from "./errors.ts";
import { unwrapParams, type Peer } from "./peer.ts";

/** Cursor is a place in an application's log of kept events: the log's identity, and the id of an event in it. */
export interface Cursor {
	log: string;
	id: number;
}

/** KeptAPI is the API an application keeping events offers its clients. */
export const KeptAPI = "goframework.io/app-spec/protocol.KeptEvents";
/** KeptVersion is the version of KeptAPI this client speaks. */
export const KeptVersion = "1.0.0";
/** NotKeptCode is the code of the error answering a cursor the log can no longer follow: the client reads its state again. */
export const NotKeptCode = "goframework.io/app-spec/protocol.ErrNotKept";

/** KeptHello is what the follower reads of an application's hello. */
export interface KeptHello {
	kept?: Cursor | null;
	offers?: { name: string; version?: string }[];
}

interface Item {
	id?: unknown;
	event?: unknown;
	params?: unknown;
}

function sameMajor(a: string, b: string): boolean {
	const major = (version: string) => version.replace(/^v/, "").split(".")[0];
	return a === "" || b === "" || major(a) === major(b);
}

function message(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

/**
 * cursorOf reads a cursor as the application writes it: its log or its id
 * left out when empty or 0 (Go's omitempty), as a cursor of the first event
 * of a log, or of a log that kept none, is written.
 */
function cursorOf(value: unknown): Cursor {
	const cursor = value as { log?: unknown; id?: unknown } | null | undefined;
	return { log: typeof cursor?.log === "string" ? cursor.log : "", id: typeof cursor?.id === "number" ? cursor.id : 0 };
}

/**
 * Follower follows an application's kept events for a client, across the
 * connections it makes, into its event handlers, as Go's protocol.Follower
 * does: at each connection from the client's cursor; when there is none, or
 * the events after it are kept no longer, from a position taken before
 * reload reads the client's state again. Handlers see the kept events in
 * order, each once. A handler that may refuse one (ConnectOptions.kept) and
 * does leaves the cursor before it: the follower leaves the stream, waits,
 * and follows again from there, nothing after the event handled first.
 * caughtUp runs once the client has handled every kept event up to where
 * the log stood when it began following: once a connection, and again after
 * the state is read again.
 */
export class Follower {
	private readonly takesEvents: boolean;
	private readonly reload: (() => Promise<Partial<Cursor> | void>) | undefined;
	private readonly caughtUp: (() => Promise<void>) | undefined;
	private readonly report: (problem: string) => void;
	private place: Cursor;
	private load: boolean;
	private turn: Promise<void> = Promise.resolve();

	constructor(
		takesEvents: boolean, from: Partial<Cursor> | undefined, reload: (() => Promise<Partial<Cursor> | void>) | undefined,
		caughtUp: (() => Promise<void>) | undefined, report: (problem: string) => void,
	) {
		this.takesEvents = takesEvents;
		this.reload = reload;
		this.caughtUp = caughtUp;
		this.report = report;
		this.place = cursorOf(from);
		this.load = this.place.log === "" && this.place.id === 0;
	}

	/** cursor is the cursor of the last kept event handled, or of the state read again. */
	get cursor(): Cursor {
		return { ...this.place };
	}

	/** follows tells whether the client follows the kept events of the application whose hello this is: it then lists KeptAPI among its uses. */
	follows(hello: KeptHello): boolean {
		return this.takesEvents && hello.kept !== undefined && hello.kept !== null &&
			(hello.offers ?? []).some((api) => api.name === KeptAPI && sameMajor(api.version ?? "", KeptVersion));
	}

	/** follow follows over peer, the connection whose hello this is, until it ends; one connection's after the previous one's. */
	follow(peer: Peer, hello: KeptHello): Promise<void> {
		const run = this.turn.then(() => this.run(peer, hello));
		this.turn = run.catch(() => {});
		return run;
	}

	private set(cursor: Cursor): void {
		this.place = { ...cursor };
		this.load = false;
	}

	/** tellCaughtUp runs caughtUp, reporting its failure. */
	private async tellCaughtUp(): Promise<void> {
		try {
			await this.caughtUp?.();
		} catch (error) {
			this.report(`kept events: caught up: ${message(error)}`);
		}
	}

	private async run(peer: Peer, hello: KeptHello): Promise<void> {
		if (!this.follows(hello)) {
			let read = this.reload === undefined;
			for (let attempt = 0; !read && !peer.ended; attempt++) {
				try {
					await this.reload!();
					read = true;
				} catch (error) {
					await this.wait(peer, attempt, "reading the state again", error);
				}
			}
			if (read && !peer.ended) {
				await this.tellCaughtUp(); // the state read: as current as events that are not kept let it be
			}
			return;
		}
		const start = cursorOf(hello.kept);
		let target = start.id; // where the log stood as following began: caught up once the cursor is there
		let caught = false; // caughtUp ran since the connection began, or since the state was read again
		const reached = async (cursor: Cursor): Promise<void> => {
			if (!caught && cursor.id >= target && !peer.ended) {
				caught = true;
				await this.tellCaughtUp();
			}
		};
		let fromHello = true; // the first position taken on this connection is the hello's
		let attempt = 0; // failures in a row, for the wait before trying again
		while (!peer.ended) {
			let cursor = this.cursor;
			let load = this.load;
			if (!load && cursor.log !== "" && cursor.log !== start.log) {
				this.report(`kept events: the application's log is ${start.log}, the client's cursor ${cursor.log}#${cursor.id}: reading the state again`);
				load = true;
			}
			if (load) {
				let position = start;
				if (!fromHello) {
					try {
						position = cursorOf(await peer.call(`${KeptAPI}.Newest`, {}, "value"));
					} catch (error) {
						await this.wait(peer, attempt++, "reading where the kept events are", error);
						continue;
					}
				}
				fromHello = false;
				cursor = { log: position.log, id: position.id };
				if (this.reload !== undefined) {
					let loaded: Cursor | undefined;
					try {
						const answered = await this.reload();
						loaded = answered ? cursorOf(answered) : undefined;
					} catch (error) {
						await this.wait(peer, attempt++, "reading the state again", error);
						continue;
					}
					if (loaded && (loaded.log !== "" || loaded.id > 0)) {
						if (loaded.log === "" || loaded.log === position.log) {
							cursor = { log: position.log, id: loaded.id };
						} else {
							this.report(`kept events: the state read again is at ${loaded.log}#${loaded.id}, of another log than ${position.log}: following from ${position.id}`);
						}
					}
				}
				this.set(cursor);
				target = position.id; // caught up again once there
				caught = false;
			}
			if (cursor.log === "") {
				cursor = { log: start.log, id: cursor.id }; // a cursor saved without its log's identity: this log's
			}
			let progressed = false;
			let failure: unknown;
			let refused: { event: string; cursor: Cursor; error: unknown } | undefined;
			try {
				const items = (await peer.call(`${KeptAPI}.Follow`, { value: cursor }, "items")) as AsyncIterable<unknown>;
				fromHello = false; // what is followed now is past the hello's position
				await reached(cursor);
				for await (const raw of items) {
					const item = raw as Item;
					if (typeof item?.id !== "number" || item.id <= cursor.id) {
						continue; // had already
					}
					const next: Cursor = { log: cursor.log, id: item.id };
					if (typeof item.event === "string" && item.event !== "") {
						const refusal = await peer.handleKept(item.event, unwrapParams(item.params), { ...next });
						if (refusal !== undefined) {
							// The stream left, what it held after the event with it: the
							// event comes again when following again from the cursor.
							refused = { event: item.event, cursor: next, error: refusal.error };
							break;
						}
					}
					cursor = next;
					this.set(cursor);
					progressed = true;
					await reached(cursor);
				}
			} catch (error) {
				failure = error;
			}
			if (peer.ended) {
				return;
			}
			if (progressed) {
				attempt = 0;
			}
			if (refused !== undefined) {
				await this.wait(peer, attempt++, `handling ${refused.event} at ${refused.cursor.log}#${refused.cursor.id}`, refused.error);
			} else if (failure instanceof RemoteError && failure.is(NotKeptCode)) {
				this.report(`kept events: ${failure.message}`);
				this.load = true;
				if (attempt > 0) {
					await this.wait(peer, attempt - 1, "following the kept events", failure); // lost again at once
				}
				attempt++;
			} else {
				await this.wait(peer, attempt++, "following the kept events", failure ?? new Error("the stream ended"));
			}
		}
	}

	/** wait reports a failure and waits before trying again: 1, 2, 4 ... 60 seconds, or until the connection ends. */
	private async wait(peer: Peer, attempt: number, what: string, error: unknown): Promise<void> {
		if (peer.ended) {
			return;
		}
		const delay = attempt < 6 ? 1000 * 2 ** attempt : 60_000;
		this.report(`kept events: ${what}: ${message(error)}; again in ${delay / 1000} seconds`);
		let timer: ReturnType<typeof setTimeout> | undefined;
		await Promise.race([new Promise((resolve) => (timer = setTimeout(resolve, delay))), peer.done]);
		clearTimeout(timer);
	}
}
