// States: an application keeping the newest value of each thing its
// clients show (Go's Clients.SetState) says in its hello where its states
// stand and offers States; a client taking states lists States among its
// welcome's uses and the states' names among its events, and calls Follow
// with the position it had, getting the newest value of each state changed
// since (every one, at another identity), the snapshot's end naming every
// state it has, then each change, as a typed stream. app.md, R13.

import { unwrapParams, type Peer } from "./peer.ts";

/** StatePosition is where a client's states stand: the identity of the application's states, and the revision of the newest it had. */
export interface StatePosition {
	log: string;
	revision: number;
}

/** StatesAPI is the API an application keeping states offers its clients. */
export const StatesAPI = "goframework.io/app-spec/protocol.States";
/** StatesVersion is the version of StatesAPI this client speaks. */
export const StatesVersion = "1.0.0";

/** A state's handler: its value (undefined when deleted), its revision (none from an application of an earlier release), whether it was deleted. */
export type StateHandler = (value: unknown, revision?: number, deleted?: boolean) => unknown;

/** StatesHello is what the follower reads of an application's hello. */
export interface StatesHello {
	states?: { log?: string; revision?: number } | null;
	offers?: { name: string; version?: string }[];
}

interface Item {
	name: string;
	revision: number;
	params?: unknown;
	deleted: boolean;
	names?: string[];
}

function itemOf(raw: unknown): Item | undefined {
	const item = raw as { name?: unknown; revision?: unknown; params?: unknown; deleted?: unknown; names?: unknown } | null;
	if (item === null || typeof item !== "object") {
		return undefined;
	}
	return {
		name: typeof item.name === "string" ? item.name : "",
		revision: typeof item.revision === "number" ? item.revision : 0,
		params: item.params,
		deleted: item.deleted === true,
		names: Array.isArray(item.names) ? item.names.filter((name): name is string => typeof name === "string") : undefined,
	};
}

function before(a: Item, b: Item): number {
	return a.revision !== b.revision ? a.revision - b.revision : a.name < b.name ? -1 : a.name > b.name ? 1 : 0;
}

function sameMajor(a: string, b: string): boolean {
	const major = (version: string) => version.replace(/^v/, "").split(".")[0];
	return a === "" || b === "" || major(a) === major(b);
}

function message(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

/**
 * StateFollower follows an application's states for a client, across the
 * connections it makes, into its state handlers, as Go's
 * protocol.StateFollower does: at each connection from the client's
 * position, a state it had and the snapshot does not name deleted, a value
 * it had already not handled again; its reader keeps the newest value read
 * of each name and hands the newest to the handler when it is free, so a
 * slow handler skips the values replaced meanwhile. caughtUp runs once a
 * connection, when the snapshot is handled.
 */
export class StateFollower {
	private readonly handlers: Record<string, StateHandler>;
	private readonly caughtUp: (() => Promise<void>) | undefined;
	private readonly report: (problem: string) => void;
	private place: StatePosition = { log: "", revision: 0 };
	private readonly held = new Map<string, number>(); // the states the client has, with their revisions in heldLog
	private heldLog = "";
	private turn: Promise<void> = Promise.resolve();

	constructor(handlers: Record<string, StateHandler>, caughtUp: (() => Promise<void>) | undefined, report: (problem: string) => void) {
		this.handlers = handlers;
		this.caughtUp = caughtUp;
		this.report = report;
	}

	/** position is where the client's states stand: what it follows on from at its next connection. */
	get position(): StatePosition {
		return { ...this.place };
	}

	/** follows tells whether the client follows the states of the application whose hello this is: it then lists StatesAPI among its uses. */
	follows(hello: StatesHello): boolean {
		return Object.keys(this.handlers).length > 0 && hello.states !== undefined && hello.states !== null &&
			(hello.offers ?? []).some((api) => api.name === StatesAPI && sameMajor(api.version ?? "", StatesVersion));
	}

	/** follow follows over peer, the connection whose hello this is, until it ends; one connection's after the previous one's. */
	follow(peer: Peer, hello: StatesHello): Promise<void> {
		const run = this.turn.then(() => this.run(peer, hello));
		this.turn = run.catch(() => {});
		return run;
	}

	private async tellCaughtUp(): Promise<void> {
		try {
			await this.caughtUp?.();
		} catch (error) {
			this.report(`states: caught up: ${message(error)}`);
		}
	}

	private async run(peer: Peer, hello: StatesHello): Promise<void> {
		if (!this.follows(hello)) {
			if (!peer.ended) {
				await this.tellCaughtUp();
			}
			return;
		}
		const log = hello.states?.log ?? "";
		let caught = false;
		const reached = async (): Promise<void> => {
			if (!caught && !peer.ended) {
				caught = true;
				await this.tellCaughtUp();
			}
		};
		for (let attempt = 0; !peer.ended; attempt++) {
			let progressed = false;
			let failure: unknown;
			try {
				const items = (await peer.call(`${StatesAPI}.Follow`, { value: this.position }, "items")) as AsyncIterable<unknown>;
				({ progressed, failure } = await this.handle(peer, log, items, reached));
			} catch (error) {
				failure = error;
			}
			if (peer.ended) {
				return;
			}
			if (progressed) {
				attempt = 0;
			}
			await this.wait(peer, attempt, failure ?? new Error("the stream ended"));
		}
	}

	/** handle gives the stream's states to their handlers, the newest of each name when they are slower than the stream, until it ends. */
	private async handle(peer: Peer, log: string, items: AsyncIterable<unknown>, reached: () => Promise<void>): Promise<{ progressed: boolean; failure: unknown }> {
		const pending = new Map<string, Item>(); // read and not handled yet: the newest of each name
		let end: Item | undefined; // the snapshot's end, once read
		let wake: (() => void) | undefined;
		let woken = false; // the reader read something since the handlers' loop last took what was read
		const signal = () => {
			woken = true;
			wake?.();
		};
		let finished = false;
		let failure: unknown;
		if (this.heldLog !== log) { // the revisions held are another identity's: none is had already here
			for (const name of this.held.keys()) {
				this.held.set(name, 0);
			}
			this.heldLog = log;
		}
		const reader = (async () => {
			try {
				for await (const raw of items) {
					const item = itemOf(raw);
					if (item === undefined) {
						continue;
					}
					if (item.name === "") {
						const named = new Set(item.names ?? []);
						for (const name of this.held.keys()) {
							if (!named.has(name)) {
								pending.set(name, { name, revision: item.revision, deleted: true });
							}
						}
						end = item;
					} else if (item.deleted) {
						if (this.held.has(item.name)) {
							pending.set(item.name, item);
						} else {
							pending.delete(item.name); // never had: neither its value nor its deletion
						}
					} else if (!this.held.has(item.name) || item.revision > this.held.get(item.name)!) {
						pending.set(item.name, item);
					}
					signal();
				}
			} catch (error) {
				failure = error;
			} finally {
				finished = true;
				signal();
			}
		})();
		let progressed = false;
		for (;;) {
			woken = false;
			const batch = [...pending.values()].sort(before);
			pending.clear();
			for (const item of batch) {
				if (item.deleted) {
					this.held.delete(item.name);
				} else {
					this.held.set(item.name, item.revision);
				}
			}
			const snapshotEnd = end;
			for (const item of batch) {
				const handler = this.handlers[item.name];
				if (handler !== undefined) {
					await peer.handleState(item.name, handler, item.deleted ? undefined : unwrapParams(item.params), item.revision, item.deleted);
				}
				progressed = true;
				if (snapshotEnd !== undefined) {
					this.place = { log, revision: Math.max(item.revision, this.place.log === log ? this.place.revision : 0) };
				}
			}
			if (snapshotEnd !== undefined) {
				if (this.place.log !== log || this.place.revision < snapshotEnd.revision) {
					this.place = { log, revision: snapshotEnd.revision };
				}
				await reached();
			}
			if (woken) {
				continue; // read while the handlers ran: a value, or the snapshot's end
			}
			if (finished || peer.ended) {
				break;
			}
			await new Promise<void>((resolve) => (wake = resolve));
			wake = undefined;
		}
		await reader;
		return { progressed, failure };
	}

	/** wait reports a failure and waits before trying again: 1, 2, 4 ... 60 seconds, or until the connection ends. */
	private async wait(peer: Peer, attempt: number, error: unknown): Promise<void> {
		if (peer.ended) {
			return;
		}
		const delay = attempt < 6 ? 1000 * 2 ** attempt : 60_000;
		this.report(`states: following them: ${message(error)}; again in ${delay / 1000} seconds`);
		let timer: ReturnType<typeof setTimeout> | undefined;
		await Promise.race([new Promise((resolve) => (timer = setTimeout(resolve, delay))), peer.done]);
		clearTimeout(timer);
	}
}
