// A client of a goframework application, over WebSocket: the browser's, or
// Node's, which has the same API. The client is the protocol's plugin side:
// it writes the protocol line, presents its name and token in
// plugin.connect, answers the application's hello, then calls the
// application's APIs, takes its events and answers its calls.

import { Magic, ProtocolVersion, Subprotocol, tokenSubprotocol } from "./frames.ts";
import { NotConnectedError, RefusedError, RemoteError } from "./errors.ts";
import { Follower, KeptAPI, KeptVersion, type Cursor, type KeptHello } from "./kept.ts";
import { StateFollower, StatesAPI, StatesVersion, type StateHandler, type StatesHello } from "./states.ts";
import {
	Peer, type CallArguments, type CallOptions, type Caller, type Implementation, type Limits, type ResultKind,
	type Session, type SessionOpener,
} from "./peer.ts";

/** An API by its name and version. */
export interface API {
	name: string;
	version?: string;
	functions?: string[];
	sessions?: boolean;
}

/** The level names of a log record. */
export type Level = "trace" | "debug" | "info" | "success" | "warning" | "error" | "fatal" | "panic";

/** ConnectOptions say how a client reaches its application, and what it is. */
export interface ConnectOptions {
	/** url is the application's clients' WebSocket: "wss://board.example.com/clients", "ws://127.0.0.1:7080/clients". */
	url: string;
	/** name is what the client is ("web"); version its own version. */
	name: string;
	version?: string;
	/** token admits the client, sent as the WebSocket's token subprotocol and in plugin.connect. */
	token?: string;
	/** reconnect dials again whenever the connection ends or cannot be made, after up to 1, 2, 4 ... 60 seconds, until close. */
	reconnect?: boolean;
	/** onConnected runs after each connection's handshake: subscribe, open the sessions again. */
	onConnected?: (connection: Connection) => void;
	/**
	 * from is where the client follows on the events its application keeps
	 * (Go's ClientsConfig.Kept) at its first connection: the cursor of the
	 * last kept event a page before handled, which it saved (a handler's
	 * second argument, or connection.cursor). Without it the client reads its
	 * state first (onReload). At each connection after the first it follows
	 * on from the last kept event it handled, missing none while the
	 * application keeps them. A cursor as the application writes it, its log
	 * or id left out when empty or 0 (a state's, typed by stub -typescript),
	 * is taken as one.
	 */
	from?: Partial<Cursor>;
	/**
	 * onReload reads the client's state again from the application when the
	 * kept events cannot be followed on: at the first connection without
	 * from, and after events were lost (the client was away longer than the
	 * application keeps them, or the application's log is another: it
	 * restarted with them in memory). It returns the cursor its state is
	 * current at, which the application answers with its state, or nothing
	 * for the position taken before it began, after which events kept while
	 * it read come again. Kept events wait meanwhile; it is tried again (1,
	 * 2, 4 ... 60 seconds) while it fails. Without it a client follows on
	 * from that position, and what was lost stays lost. With an application
	 * keeping no events, it runs at each connection. The cursor may be one as
	 * the application writes it, its log or id left out when empty or 0 (a
	 * state's, typed by stub -typescript).
	 */
	onReload?: (connection: Connection) => Partial<Cursor> | void | Promise<Partial<Cursor> | void>;
	/**
	 * onCaughtUp runs once the client has caught up with the events its
	 * application keeps and with its states: at each connection, once it has
	 * handled every kept event up to where the application's log stood when
	 * the connection was made and the newest value of every state it takes,
	 * and again after events were lost, once it has handled those up to where
	 * the log stood when onReload began. A page says there that it is current
	 * ("online" after "syncing"). With an application keeping no events, the
	 * kept events' part is done at each connection once onReload has read
	 * the state, or at once; with one keeping no states, or a client taking
	 * none, the states' part is done at once. It is awaited: kept events and
	 * states wait while it runs.
	 */
	onCaughtUp?: (connection: Connection) => unknown;
	/** onDisconnected runs when a connection ends, with why. */
	onDisconnected?: (error: Error) => void;
	/**
	 * onStatus is told how the connection stands, each time that changes: a
	 * dial beginning ("connecting"), a connection made ("connected"), a
	 * dial failed or a connection ended, with why and how long until the next
	 * dial ("waiting"), and the client done dialling ("closed"). So a page
	 * says "cannot reach the application, trying again in 4 s" rather than
	 * "connecting" for ever, which onConnected and onDisconnected, told of
	 * connections made, cannot tell it. Statuses come in order, a
	 * connection's "connected" before onConnected; a handler that throws is
	 * reported.
	 */
	onStatus?: (status: Status) => void;
	/** implementations are the APIs the client offers the application (stub -typescript writes implement<API>). */
	implementations?: Implementation[];
	/**
	 * events are the application's events the client takes, by name; a kept
	 * event's handler is given its cursor after the payload. A handler that
	 * throws, or whose promise rejects, is reported, and the event is had
	 * (kept's handlers may refuse a kept one). stub -typescript's
	 * <api>Events(handlers) types them by their payloads.
	 */
	events?: Record<string, (payload: unknown, cursor?: Cursor) => unknown>;
	/**
	 * kept are handlers of the application's events, by name, as events'
	 * (each name in one of the two), that may refuse a kept event: one that
	 * throws, or whose promise rejects (a full disk, a store locked: what it
	 * did with the event is not done), leaves the client's cursor before the
	 * event, and the client has it again after a wait (1, 2, 4 ... 60 seconds
	 * while refusals follow each other), on this connection or the next,
	 * nothing after it handled before it; the connection goes on meanwhile.
	 * An event that is not kept is had once, its handler's failure reported.
	 * stub -typescript's <api>Events(handlers) types them too.
	 */
	kept?: Record<string, (payload: unknown, cursor?: Cursor) => unknown>;
	/**
	 * states are handlers of the application's states, by name (Go's
	 * Clients.SetState and Client.SetState), each name in states or in
	 * events and kept, not both: at each connection the newest value of the
	 * state, and at a connection after the first only when it changed since,
	 * then each newer value, never an older one; a slow handler is given the
	 * newest, the values replaced meanwhile skipped. A handler is given the
	 * value, its revision, and whether the state was deleted (its value
	 * undefined then); it is awaited, and one that throws is reported. From
	 * an application of an earlier release, which sends its states as
	 * events, each event of the name is given to the handler, without a
	 * revision. stub -typescript's <api>States(handlers) types them by their
	 * values.
	 */
	states?: Record<string, StateHandler>;
	/** report takes what goes wrong where no caller can be told: a dropped event, a failing handler. */
	report?: (problem: string) => void;
	/** eventQueue is how many events wait, each way, before more are dropped: 1024. */
	eventQueue?: number;
	/** limits are what the client takes: messages, a stream's window, buffers. */
	limits?: Partial<Limits>;
	/** WebSocket is the WebSocket class: the global one by default. */
	WebSocket?: typeof WebSocket;
	/** signal gives up connecting. */
	signal?: AbortSignal;
}

/** Status is how a client's connection stands, told to onStatus at each change. */
export interface Status {
	/**
	 * phase is where the connection is: "connecting" while a dial and its
	 * handshake run; "connected" once the connection is usable; "waiting"
	 * after a dial failed or the connection ended, until the next dial;
	 * "closed" once the client dials no more: closed, refused at its first
	 * connection, given up (signal), or, without reconnect, its first dial
	 * failed or its connection ended.
	 */
	phase: "connecting" | "connected" | "waiting" | "closed";
	/**
	 * attempt counts the dials since the last connection was made, or since
	 * connect, from 1: the one beginning, made or failed; 0 when the status
	 * follows a connection's end rather than a dial's failure.
	 */
	attempt: number;
	/** error is why the dial failed or the connection ended ("waiting", "closed"); none after close. */
	error?: Error;
	/** retryIn is how long the client waits before its next dial, in milliseconds ("waiting"). */
	retryIn?: number;
}

/** Connection is a client's connection to its application, made again as reconnect says. */
export interface Connection extends Caller, SessionOpener {
	/** connected tells whether there is a connection now. */
	readonly connected: boolean;
	/** application is the application's name and version, from the last handshake. */
	readonly application: { name: string; version?: string };
	/** settings are what the application gives its clients, from the last handshake. */
	readonly settings: unknown;
	/** cursor is the cursor of the last kept event handled, or of the state read again (onReload): what a page saves to follow on from it (from). */
	readonly cursor: Cursor;
	/** publish sends an event to the application; false when too many wait to be sent. */
	publish(event: string, payload?: unknown): boolean;
	/** log writes a record to the application's log, under the client's name. */
	log(level: Level, message: string, attrs?: Record<string, unknown>): void;
	/** close ends the connection, and dials no more. */
	close(): Promise<void>;
	/** done settles once the client is over: closed, or, without reconnect, its connection ended. */
	readonly done: Promise<void>;
}

const connectTimeout = 10_000;
const pingInterval = 5_000;
const pingTimeout = 5_000;
const stableConnection = 60_000;

/** delay is the wait before dialling again: up to 1, 2, 4 ... 60 seconds, at least half of that. */
function delay(again: number): number {
	const cap = Math.min(60_000, 1000 * 2 ** Math.min(again - 1, 6));
	return cap / 2 + Math.random() * (cap / 2);
}

interface Link {
	peer: Peer;
	application: { name: string; version?: string };
	settings: unknown;
	offers: API[];
	hello: KeptHello & StatesHello;
	stop: Promise<string>;
}

/**
 * connect connects to the application and returns once the handshake is
 * done. Without reconnect it fails with the first connection's failure; with
 * it, it waits for a connection until options.signal ends, but a refusal (a
 * wrong token) fails it at once.
 */
export async function connect(options: ConnectOptions): Promise<Connection> {
	if (!options.name) {
		throw new Error("a client needs a name");
	}
	for (const name of Object.keys(options.kept ?? {})) {
		if (Object.hasOwn(options.events ?? {}, name)) {
			throw new Error(`the event ${name} is taken twice: in events and in kept`);
		}
	}
	for (const name of Object.keys(options.states ?? {})) {
		if (Object.hasOwn(options.events ?? {}, name) || Object.hasOwn(options.kept ?? {}, name)) {
			throw new Error(`the state ${name} is taken as an event too`);
		}
	}
	const client = new Client(options);
	await client.first;
	return client;
}

class Client implements Connection {
	private readonly options: ConnectOptions;
	private readonly uses = new Map<string, string>();
	private readonly follower: Follower;
	private readonly stateFollower: StateFollower;
	private caughtUpParts = { kept: false, states: false }; // the connection's followers caught up
	private caughtUpTurn: Promise<void> = Promise.resolve();
	private current: Link | undefined;
	private closing = false;
	private wakeClose: (() => void) | undefined;
	private readonly closed: Promise<void>;
	readonly first: Promise<void>;
	readonly done: Promise<void>;
	private finishDone!: () => void;

	constructor(options: ConnectOptions) {
		this.options = options;
		const reload = options.onReload;
		const takesEvents = Object.keys(options.events ?? {}).length + Object.keys(options.kept ?? {}).length > 0;
		this.follower = new Follower(takesEvents, options.from,
			reload === undefined ? undefined : async () => await reload(this),
			async () => await this.caught("kept"),
			(problem) => options.report?.(problem));
		this.stateFollower = new StateFollower(options.states ?? {}, async () => await this.caught("states"),
			(problem) => options.report?.(problem));
		this.closed = new Promise((resolve) => (this.wakeClose = resolve));
		this.done = new Promise((resolve) => (this.finishDone = resolve));
		let settle!: (error?: Error) => void;
		this.first = new Promise<void>((resolve, reject) => (settle = (error) => (error ? reject(error) : resolve())));
		void this.run(settle);
	}

	get connected(): boolean {
		return this.current !== undefined && !this.current.peer.ended;
	}

	get application(): { name: string; version?: string } {
		return this.current?.application ?? { name: "" };
	}

	get settings(): unknown {
		return this.current?.settings;
	}

	get cursor(): Cursor {
		return this.follower.cursor;
	}

	/** eventNames are the events the client takes: events', kept's and states', sorted. */
	private eventNames(): string[] {
		return [...Object.keys(this.options.events ?? {}), ...Object.keys(this.options.kept ?? {}), ...Object.keys(this.options.states ?? {})].sort();
	}

	/**
	 * caught hears that a follower caught up on the current connection:
	 * onCaughtUp runs once both have, and again each time the kept events'
	 * follower catches up again after a loss; one run at a time.
	 */
	private async caught(which: "kept" | "states"): Promise<void> {
		this.caughtUpParts[which] = true;
		const parts = this.caughtUpParts;
		if (!parts.kept || !parts.states || this.options.onCaughtUp === undefined) {
			return;
		}
		const run = this.caughtUpTurn.then(async () => {
			if (this.caughtUpParts === parts) {
				await this.options.onCaughtUp!(this);
			}
		});
		this.caughtUpTurn = run.catch(() => {});
		await run;
	}

	/** run makes the connections, until close, or the first connection's end without reconnect. */
	private async run(settle: (error?: Error) => void): Promise<void> {
		let first = true;
		let again = 1; // the backoff's count, started over by a connection lasting
		let attempt = 0; // Status.attempt: the dials since the last connection
		for (;;) {
			const began = Date.now();
			let failure: Error;
			let lost = false; // failure is a connection's end, not a dial's
			attempt++;
			this.tell({ phase: "connecting", attempt });
			try {
				const link = await this.dial();
				this.tell({ phase: "connected", attempt });
				if (first) {
					first = false;
					settle();
				}
				attempt = 0;
				lost = true;
				failure = await this.serve(link);
				if (this.closing) {
					this.tell({ phase: "closed", attempt });
					break;
				}
				if (Date.now() - began > stableConnection) {
					again = 1;
				}
			} catch (error) {
				failure = error instanceof Error ? error : new Error(String(error));
				if (first && (!this.options.reconnect || failure instanceof RefusedError || this.options.signal?.aborted)) {
					settle(failure);
					this.tell({ phase: "closed", attempt, error: failure });
					break;
				}
			}
			if (this.closing) {
				this.tell({ phase: "closed", attempt: 0 });
				break;
			}
			if (!this.options.reconnect) {
				this.tell({ phase: "closed", attempt, error: failure });
				break;
			}
			const wait = delay(again);
			this.options.report?.(`${this.options.url}: ${failure.message}; connecting again`);
			this.tell({ phase: "waiting", attempt: lost ? 0 : attempt, error: failure, retryIn: Math.round(wait) });
			// A signal aborted already (by onStatus, say) gives up at once.
			const waited = this.options.signal?.aborted ? false : await Promise.race([
				new Promise<boolean>((resolve) => setTimeout(() => resolve(true), wait)),
				this.closed.then(() => false),
				new Promise<boolean>((resolve) => this.options.signal?.addEventListener("abort", () => resolve(false), { once: true })),
			]);
			if (!waited) {
				const givenUp = new Error(`connecting to ${this.options.url}: given up`);
				if (first) {
					settle(givenUp);
				}
				this.tell(this.closing ? { phase: "closed", attempt: 0 } : { phase: "closed", attempt: 0, error: givenUp });
				break;
			}
			again++;
		}
		this.finishDone();
	}

	/** tell gives onStatus the connection's status; a handler that throws is reported. */
	private tell(status: Status): void {
		try {
			this.options.onStatus?.(status);
		} catch (error) {
			this.options.report?.(`onStatus: ${error instanceof Error ? error.message : String(error)}`);
		}
	}

	/** dial makes one connection: the WebSocket, the protocol line, plugin.connect, the hello answered. */
	private async dial(): Promise<Link> {
		const Socket = this.options.WebSocket ?? globalThis.WebSocket;
		if (Socket === undefined) {
			throw new Error("no WebSocket here: give ConnectOptions.WebSocket");
		}
		const protocols = [Subprotocol];
		if (this.options.token) {
			protocols.push(tokenSubprotocol(this.options.token));
		}
		const socket = new Socket(this.options.url, protocols);
		socket.binaryType = "arraybuffer";
		await new Promise<void>((resolve, reject) => {
			const timer = setTimeout(() => {
				socket.close();
				reject(new Error(`${this.options.url}: no WebSocket within ${connectTimeout / 1000} seconds`));
			}, connectTimeout);
			socket.onopen = () => {
				clearTimeout(timer);
				resolve();
			};
			socket.onerror = () => {
				clearTimeout(timer);
				// A browser tells no more: a 401 (a wrong token), a 403 (an
				// origin not listed) and a server not there look alike.
				reject(new Error(`${this.options.url}: the WebSocket could not be opened`));
			};
		});
		if (socket.protocol !== Subprotocol) {
			socket.close();
			throw new Error(`${this.options.url} agreed on no WebSocket subprotocol; the protocol's is ${Subprotocol}`);
		}
		let stopped!: (reason: string) => void;
		const stop = new Promise<string>((resolve) => (stopped = resolve));
		let helloDone!: (error?: Error) => void;
		const hello = new Promise<void>((resolve, reject) => (helloDone = (error) => (error ? reject(error) : resolve())));
		// an application of an earlier release sends its states as events
		const asEvents = Object.entries(this.options.states ?? {}).map(([name, handler]) => [name, (payload: unknown) => handler(payload)] as const);
		const events = new Map([...Object.entries(this.options.events ?? {}), ...Object.entries(this.options.kept ?? {}), ...asEvents]);
		const refusing = new Set(Object.keys(this.options.kept ?? {}));
		const link: Partial<Link> = { stop, offers: [] };
		const peer = new Peer(
			{
				send: (bytes) => socket.send(bytes as Uint8Array<ArrayBuffer>), // made over an ArrayBuffer, never a shared one
				get bufferedAmount() {
					return socket.bufferedAmount;
				},
				close: () => socket.close(),
			},
			{
				implementations: this.options.implementations ?? [],
				events,
				refusing,
				eventQueue: this.options.eventQueue ?? 1024,
				limits: { message: this.options.limits?.message ?? 0, window: this.options.limits?.window, buffer: this.options.limits?.buffer },
				report: (problem) => this.options.report?.(problem),
				control: (method, params) => {
					switch (method) {
						case "plugin.hello":
							try {
								const welcome = this.answer(peer, link, params);
								helloDone();
								return welcome;
							} catch (error) {
								helloDone(error instanceof Error ? error : new Error(String(error)));
								throw error;
							}
						case "plugin.stop":
							stopped("the application stopped");
							return null;
					}
					throw new Error(`no control method ${method}`);
				},
			},
		);
		link.peer = peer;
		socket.onmessage = (event: MessageEvent) => {
			if (typeof event.data === "string") {
				peer.end(new Error("a text message: the protocol's are binary"));
				return;
			}
			peer.receive(new Uint8Array(event.data as ArrayBuffer));
		};
		socket.onclose = (event: CloseEvent) => {
			peer.end(new Error(event.wasClean ? "the connection is closed" : "the connection was cut"));
		};
		socket.onerror = null;
		peer.write(new TextEncoder().encode(Magic));
		try {
			const timeout = AbortSignal.timeout(connectTimeout);
			await peer.controlCall("plugin.connect", { name: this.options.name, token: this.options.token ?? "" }, { signal: timeout });
			await Promise.race([
				hello,
				peer.done.then(() => Promise.reject(peer.error)),
				new Promise((_, reject) => timeout.addEventListener("abort", () => reject(new Error("no hello within the handshake's time")), { once: true })),
			]);
		} catch (error) {
			peer.end(new Error("the handshake failed"));
			if (error instanceof RemoteError) {
				throw new RefusedError(`the application refused the connection: ${error.message}`);
			}
			throw error;
		}
		return link as Link;
	}

	/** answer checks the application's hello and answers it with the client's welcome. */
	private answer(peer: Peer, link: Partial<Link>, params: unknown): unknown {
		const hello = params as {
			protocol?: number; application?: { name: string; version?: string }; plugin?: string; settings?: unknown; offers?: API[]; limits?: Limits;
			kept?: Cursor; states?: { log?: string; revision?: number };
		};
		if (hello.protocol !== ProtocolVersion) {
			throw new Error(`the application speaks protocol ${hello.protocol}, this client ${ProtocolVersion}`);
		}
		if (hello.plugin !== this.options.name) {
			throw new Error(`the application expects the client ${JSON.stringify(hello.plugin)}, this is ${JSON.stringify(this.options.name)}`);
		}
		const offered = new Map((hello.offers ?? []).map((api) => [api.name, api.version ?? ""]));
		for (const [api, version] of this.uses) {
			if (!offered.has(api)) {
				throw new Error(`the application does not offer ${api}`);
			}
			if (!compatible(offered.get(api) ?? "", version)) {
				throw new Error(`the application offers ${api} ${offered.get(api)}, this client uses ${version}`);
			}
		}
		if (hello.limits) {
			peer.setPeerLimits(hello.limits);
		}
		link.application = hello.application ?? { name: "" };
		link.settings = hello.settings;
		link.offers = hello.offers ?? [];
		link.hello = { kept: hello.kept, states: hello.states, offers: link.offers };
		peer.setReady();
		const uses = [...this.uses].map(([name, version]) => ({ name, version }));
		if (this.follower.follows(link.hello)) {
			uses.push({ name: KeptAPI, version: KeptVersion }); // the kept events through Follow, not as events
		}
		if (this.stateFollower.follows(link.hello)) {
			uses.push({ name: StatesAPI, version: StatesVersion }); // the states through Follow, not as events
		}
		return {
			protocol: ProtocolVersion,
			plugin: { name: this.options.name, version: this.options.version ?? "" },
			offers: (this.options.implementations ?? []).map((implementation) => ({
				name: implementation.api, version: implementation.version, functions: Object.keys(implementation.functions).sort(),
			})),
			uses,
			events: this.eventNames(),
			limits: peer.limits(),
		};
	}

	/** serve keeps a connection until it ends (why), close, or the application's stop; it pings meanwhile. */
	private async serve(link: Link): Promise<Error> {
		this.current = link;
		try {
			this.options.onConnected?.(this);
		} catch (error) {
			this.options.report?.(`onConnected: ${error instanceof Error ? error.message : String(error)}`);
		}
		this.caughtUpParts = { kept: false, states: false };
		// the kept events, from the cursor; the next connection's after this one's
		void this.follower.follow(link.peer, link.hello).catch((error: unknown) => {
			this.options.report?.(`following the kept events: ${error instanceof Error ? error.message : String(error)}`);
		});
		// the states, from the position the client had
		void this.stateFollower.follow(link.peer, link.hello).catch((error: unknown) => {
			this.options.report?.(`following the states: ${error instanceof Error ? error.message : String(error)}`);
		});
		const pinging = setInterval(() => {
			link.peer.controlCall("plugin.ping", undefined, { signal: AbortSignal.timeout(pingTimeout) }).catch(() => {
				if (!link.peer.ended) {
					link.peer.end(new Error(`the application did not answer for ${pingTimeout / 1000} seconds`));
				}
			});
		}, pingInterval);
		const ended = await Promise.race([
			link.peer.done.then(() => link.peer.error ?? new Error("the connection ended")),
			link.stop.then((reason) => new Error(reason)),
			this.closed.then(() => new Error("closed")),
		]);
		clearInterval(pinging);
		if (!link.peer.ended) {
			link.peer.end(ended);
		}
		if (this.current === link) {
			this.current = undefined;
		}
		try {
			this.options.onDisconnected?.(ended);
		} catch {
			// a handler's failure is its own
		}
		return ended;
	}

	use(api: string, version: string): void {
		this.uses.set(api, version);
	}

	call(fn: string, args: CallArguments, result: ResultKind, options?: CallOptions): Promise<unknown> {
		const link = this.current;
		if (link === undefined || link.peer.ended) {
			return Promise.reject(new NotConnectedError(fn));
		}
		return link.peer.call(fn, args, result, options).catch((error: unknown) => {
			throw link.peer.ended && !(error instanceof RemoteError) && !options?.signal?.aborted ? new NotConnectedError(fn) : error;
		});
	}

	async open(api: string, version: string, params: unknown, options?: CallOptions): Promise<Session> {
		const link = this.current;
		if (link === undefined || link.peer.ended) {
			throw new NotConnectedError(`${api}.$open`);
		}
		const offered = link.offers.find((found) => found.name === api);
		if (offered === undefined) {
			throw new Error(`${api}.$open: the application does not offer it`);
		}
		if (!offered.sessions) {
			throw new Error(`${api}.$open: the application offers ${api}, but not in sessions`);
		}
		if (!compatible(offered.version ?? "", version)) {
			throw new Error(`${api}.$open: the application offers ${api} ${offered.version}; this client uses ${version}`);
		}
		return await link.peer.open(api, params, options);
	}

	publish(event: string, payload?: unknown): boolean {
		const link = this.current;
		if (link === undefined || link.peer.ended) {
			throw new NotConnectedError(event);
		}
		return link.peer.publish(event, payload);
	}

	log(level: Level, message: string, attrs?: Record<string, unknown>): void {
		this.current?.peer.notify("plugin.log", { time: new Date().toISOString(), level, message, attrs });
	}

	async close(): Promise<void> {
		this.closing = true;
		this.wakeClose?.();
		await this.done;
	}
}

/** compatible reports whether two versions share their major version, or one is not given. */
export function compatible(a: string, b: string): boolean {
	if (a === "" || b === "") {
		return true;
	}
	const major = (version: string) => version.replace(/^v/, "").split(".")[0];
	return major(a) === major(b);
}
