// The protocol's framing: every byte on a connection is in a frame,
//
//	kind (1 byte) | stream (4 bytes) | length (4 bytes) | payload (length bytes, at most 65536)
//
// kind 0 a control message, 1 a data message, 2 stream bytes, plus 128 when
// the message goes on in the next frame of its kind; stream 0 for messages.
// Integers are big-endian. A client writes the protocol line first.

/** The line a plugin, or a client, writes before its first frame. */
export const Magic = "goframework.io/app-plugin protocol 1\n";

/** The WebSocket subprotocol of the protocol's connections. */
export const Subprotocol = "v1.app-plugin.goframework.io";

/** The protocol's version, exchanged in the handshake. */
export const ProtocolVersion = 1;

export const KindControl = 0;
export const KindData = 1;
export const KindStream = 2;
const Continued = 0x80;

/** The largest payload of one frame. */
export const MaxPiece = 64 * 1024;
const HeaderSize = 9;

/** The largest message by default: 16 MiB. */
export const DefaultMessageLimit = 16 << 20;
/** The bytes of a stream its writer may send ahead by default: 4 MiB. */
export const DefaultStreamWindow = 4 << 20;
/** The largest buffer a side takes by default: 256 MiB. */
export const DefaultBufferLimit = 256 << 20;

/** ProtocolError is what breaks the protocol: the connection ends. */
export class ProtocolError extends Error {
	constructor(message: string) {
		super("protocol error: " + message);
		this.name = "ProtocolError";
	}
}

/** frame returns one frame's bytes. */
export function frame(kind: number, stream: number, payload: Uint8Array): Uint8Array {
	const bytes = new Uint8Array(HeaderSize + payload.length);
	const view = new DataView(bytes.buffer);
	view.setUint8(0, kind);
	view.setUint32(1, stream);
	view.setUint32(5, payload.length);
	bytes.set(payload, HeaderSize);
	return bytes;
}

/** messageFrames returns a message's frames, in pieces of MaxPiece. */
export function messageFrames(kind: number, message: Uint8Array): Uint8Array[] {
	const frames: Uint8Array[] = [];
	let offset = 0;
	do {
		const piece = message.subarray(offset, offset + MaxPiece);
		offset += piece.length;
		frames.push(frame(offset < message.length ? kind | Continued : kind, 0, piece));
	} while (offset < message.length);
	return frames;
}

/** Read is what a FrameReader read: a whole message, or a stream's frame. */
export type Read =
	| { kind: typeof KindControl | typeof KindData; message: Uint8Array }
	| { kind: typeof KindStream; stream: number; payload: Uint8Array };

/**
 * FrameReader reads frames from bytes arriving in any pieces (a WebSocket's
 * binary messages, read as one stream) and puts messages back together.
 */
export class FrameReader {
	private buffered: Uint8Array[] = [];
	private head = 0; // buffered's first piece not taken yet
	private size = 0;
	private pending: [Uint8Array[], Uint8Array[]] = [[], []];
	private pendingSize: [number, number] = [0, 0];
	/** messageLimit is the largest message taken. */
	messageLimit: number;

	constructor(messageLimit: number = DefaultMessageLimit) {
		this.messageLimit = messageLimit;
	}

	/** push takes bytes and returns what they complete; it throws ProtocolError. */
	push(bytes: Uint8Array): Read[] {
		if (bytes.length > 0) {
			if (this.head > 1024 && this.head * 2 > this.buffered.length) {
				this.buffered = this.buffered.slice(this.head); // the pieces taken go, now and then
				this.head = 0;
			}
			this.buffered.push(bytes);
			this.size += bytes.length;
		}
		const read: Read[] = [];
		for (;;) {
			if (this.size < HeaderSize) {
				return read;
			}
			const header = this.peek(HeaderSize);
			const view = new DataView(header.buffer, header.byteOffset, HeaderSize);
			const first = view.getUint8(0);
			const kind = first & ~Continued;
			const more = (first & Continued) !== 0;
			const stream = view.getUint32(1);
			const length = view.getUint32(5);
			if (kind > KindStream) {
				throw new ProtocolError(`a frame of unknown kind ${kind}`);
			}
			if (length > MaxPiece) {
				throw new ProtocolError(`a frame of ${length} bytes; at most ${MaxPiece}`);
			}
			if (kind === KindStream && (stream === 0 || more)) {
				throw new ProtocolError("a stream frame without a stream, or continued");
			}
			if (kind !== KindStream && stream !== 0) {
				throw new ProtocolError(`a message frame names stream ${stream}`);
			}
			if (kind !== KindStream && this.pendingSize[kind] + length > this.messageLimit) {
				throw new ProtocolError(`a message over the limit of ${this.messageLimit} bytes`);
			}
			if (this.size < HeaderSize + length) {
				return read;
			}
			this.take(HeaderSize);
			const payload = this.take(length);
			if (kind === KindStream) {
				read.push({ kind: KindStream, stream, payload });
				continue;
			}
			const channel = kind as 0 | 1;
			this.pending[channel].push(payload);
			this.pendingSize[channel] += length;
			if (!more) {
				read.push({ kind: channel, message: concat(this.pending[channel], this.pendingSize[channel]) });
				this.pending[channel] = [];
				this.pendingSize[channel] = 0;
			}
		}
	}

	private peek(n: number): Uint8Array {
		const first = this.buffered[this.head];
		if (first.length >= n) {
			return first.subarray(0, n);
		}
		const peeked = new Uint8Array(n);
		let done = 0;
		for (let index = this.head; done < n; index++) {
			const part = this.buffered[index].subarray(0, n - done);
			peeked.set(part, done);
			done += part.length;
		}
		return peeked;
	}

	private take(n: number): Uint8Array {
		if (n === 0) {
			return new Uint8Array(0); // an empty frame: a stream's end
		}
		const first = this.buffered[this.head];
		if (first.length === n) {
			this.head++;
			this.size -= n;
			return first;
		}
		const taken = new Uint8Array(n);
		let done = 0;
		while (done < n) {
			const piece = this.buffered[this.head];
			const count = Math.min(piece.length, n - done);
			taken.set(piece.subarray(0, count), done);
			done += count;
			if (count === piece.length) {
				this.head++;
			} else {
				this.buffered[this.head] = piece.subarray(count);
			}
		}
		this.size -= n;
		return taken;
	}
}

/** concat joins the first size bytes of pieces. */
export function concat(pieces: Uint8Array[], size: number): Uint8Array {
	if (pieces.length === 1 && pieces[0].length === size) {
		return pieces[0];
	}
	const joined = new Uint8Array(size);
	let offset = 0;
	for (const piece of pieces) {
		if (offset >= size) {
			break;
		}
		const part = piece.subarray(0, size - offset);
		joined.set(part, offset);
		offset += part.length;
	}
	return joined;
}

/**
 * tokenSubprotocol is how a browser presents its token at a WebSocket's
 * handshake, as it cannot set the Authorization header: a second
 * subprotocol, "bearer." and the token in base64url without padding.
 */
export function tokenSubprotocol(token: string): string {
	const bytes = new TextEncoder().encode(token);
	let binary = "";
	for (const byte of bytes) {
		binary += String.fromCharCode(byte);
	}
	return "bearer." + btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
}
