// One side of a connection: calls both ways, notifications, events, streams
// within their windows, buffers, typed streams, sessions. A client is the
// protocol's plugin side: it numbers its calls, streams and sessions with
// even numbers.

import {
	DefaultBufferLimit, DefaultMessageLimit, DefaultStreamWindow, FrameReader, KindControl, KindData, KindStream,
	MaxPiece, ProtocolError, concat, frame, messageFrames,
} from "./frames.ts";
import { Codes, NoSessionError, RemoteError, codesOf } from "./errors.ts";
import type { Cursor } from "./kept.ts";

/** What a call's result is decoded as. */
export type ResultKind = "none" | "value" | "bytes" | "buffer" | "items";

/** CallOptions: signal cancels the call, on both sides. */
export interface CallOptions {
	signal?: AbortSignal;
}

/** ByteSource is bytes given to a call as a stream: all at once, or in pieces. */
export type ByteSource = Uint8Array | AsyncIterable<Uint8Array> | ReadableStream<Uint8Array>;

/**
 * ByteStream is a stream of bytes a call returned: read it with for await,
 * or readAll; cancel abandons it, and its writer stops.
 */
export interface ByteStream extends AsyncIterable<Uint8Array> {
	readAll(): Promise<Uint8Array>;
	cancel(reason?: string): void;
}

/** CallArguments are a call's inputs: a value, then a stream or a buffer. */
export interface CallArguments {
	value?: unknown;
	stream?: ByteSource;
	buffer?: Uint8Array;
}

/** Caller calls the functions of the APIs the other side offers. */
export interface Caller {
	use(api: string, version: string): void;
	call(fn: string, args: CallArguments, result: ResultKind, options?: CallOptions): Promise<unknown>;
}

/** Session is a session opened on the other side: its calls go to it. */
export interface Session extends Caller {
	readonly id: number;
	readonly api: string;
	/** close closes it: the other side closes its implementation. */
	close(options?: CallOptions): Promise<void>;
	/** done settles when the session ends: closed, or its connection ended. */
	readonly done: Promise<void>;
}

/** SessionOpener opens sessions of an API the other side offers in sessions. */
export interface SessionOpener {
	open(api: string, version: string, params: unknown, options?: CallOptions): Promise<Session>;
}

/** HandlerContext is what a function the client offers gets: signal ends with its call. */
export interface HandlerContext {
	signal: AbortSignal;
}

/**
 * FunctionImplementation is one function the client offers: whether it
 * takes a value, what stream or buffer follows it, what it returns.
 */
export interface FunctionImplementation {
	input?: boolean;
	stream?: "bytes" | "buffer";
	result: ResultKind;
	call(input: unknown, stream: unknown, context: HandlerContext): unknown;
}

/** Implementation is an API the client offers, by its functions' names. */
export interface Implementation {
	api: string;
	version: string;
	functions: Record<string, FunctionImplementation>;
}

/** Limits are what a side takes: the other side keeps to them. */
export interface Limits {
	message: number;
	window?: number;
	buffer?: number;
}

/** Transport carries a connection's bytes: a WebSocket's binary messages. */
export interface Transport {
	send(bytes: Uint8Array): void;
	readonly bufferedAmount: number;
	close(): void;
}

/** PeerOptions configure a Peer. */
export interface PeerOptions {
	implementations: Implementation[];
	/** events are the handlers of the events taken, by name; a kept event's is given its cursor too. */
	events: Map<string, (payload: unknown, cursor?: Cursor) => unknown>;
	/** refusing names the events whose handlers may refuse a kept one (ConnectOptions.kept): handleKept returns their failure. */
	refusing?: Set<string>;
	/** control takes the control calls and notifications the peer does not: hello, stop. */
	control: (method: string, params: unknown) => unknown;
	report: (problem: string) => void;
	eventQueue: number;
	limits: Limits;
}

/** The bytes a peer lets wait in its transport before it waits itself. */
const HighWater = 1 << 20;
/** The frames sent together in one of the transport's messages, at most. */
const BatchBytes = 256 << 10;
/** The streams a peer reads at once, at most. */
const MaxStreams = 1024;

interface Pending {
	resolve: (message: Message) => void;
	reject: (error: Error) => void;
}

interface Message {
	jsonrpc: string;
	id?: number;
	method?: string;
	session?: number;
	params?: unknown;
	result?: unknown;
	error?: { code: number; message: string; data?: unknown };
}

const encoder = new TextEncoder();
const decoder = new TextDecoder();

/** Peer is one side of a connection, reading what the transport receives. */
export class Peer {
	private readonly transport: Transport;
	private readonly options: PeerOptions;
	private readonly reader: FrameReader;
	private readonly functions = new Map<string, FunctionImplementation>();
	private nextCall = 0;
	private nextStream = 0;
	private nextSession = 0;
	private readonly pending = new Map<number, Pending>();
	private readonly handling = new Map<number, AbortController>();
	private readonly reading = new Map<number, Incoming>();
	private readonly writing = new Map<number, Outgoing>();
	private readonly controlQueue: Uint8Array[] = [];
	private readonly dataQueue: Uint8Array[] = [];
	private readonly streamQueue: (Uint8Array | Uint8Array[])[] = [];
	private streamTurn = false;
	private pumpTimer: ReturnType<typeof setTimeout> | undefined;
	private readonly events: { name: string; payload: unknown }[] = [];
	private delivering = false;
	private turn: Promise<void> = Promise.resolve(); // an event handler's: those of events, kept events and states take turns
	private ready = false;
	private endError: Error | undefined;
	private endDone!: () => void;
	/** done settles when the connection ends; error then says why. */
	readonly done: Promise<void>;
	messageLimit: number;
	sendWindow = DefaultStreamWindow;
	sendBuffer = DefaultBufferLimit;

	constructor(transport: Transport, options: PeerOptions) {
		this.transport = transport;
		this.options = options;
		this.messageLimit = options.limits.message || DefaultMessageLimit;
		this.reader = new FrameReader(this.messageLimit);
		for (const implementation of options.implementations) {
			for (const [name, implemented] of Object.entries(implementation.functions)) {
				this.functions.set(`${implementation.api}.${name}`, implemented);
			}
		}
		this.done = new Promise((resolve) => (this.endDone = resolve));
	}

	/** error tells why the connection ended; undefined while it lasts. */
	get error(): Error | undefined {
		return this.endError;
	}

	get ended(): boolean {
		return this.endError !== undefined;
	}

	/** limits are what this side takes, for its handshake. */
	limits(): Limits {
		return {
			message: this.messageLimit,
			window: this.options.limits.window ?? DefaultStreamWindow,
			buffer: this.options.limits.buffer ?? DefaultBufferLimit,
		};
	}

	/** setPeerLimits takes what the other side takes, from its handshake. */
	setPeerLimits(limits: Limits): void {
		if (limits.message > 0 && limits.message < this.messageLimit) {
			this.messageLimit = limits.message;
		}
		if (limits.window && limits.window > 0) {
			this.sendWindow = limits.window;
		}
		if (limits.buffer && limits.buffer > 0) {
			this.sendBuffer = limits.buffer;
		}
	}

	/** setReady lets data calls through: the handshake is done. */
	setReady(): void {
		this.ready = true;
	}

	/** write sends bytes as they are, before any frame: the protocol line. */
	write(bytes: Uint8Array): void {
		this.transport.send(bytes);
	}

	/** receive takes bytes the transport received. */
	receive(bytes: Uint8Array): void {
		if (this.ended) {
			return;
		}
		try {
			for (const read of this.reader.push(bytes)) {
				if (read.kind === KindStream) {
					this.streamFrame(read.stream, read.payload);
					continue;
				}
				let message: Message;
				try {
					message = JSON.parse(decoder.decode(read.message)) as Message;
				} catch {
					throw new ProtocolError("not JSON");
				}
				if (message === null || typeof message !== "object" || message.jsonrpc !== "2.0") {
					throw new ProtocolError("not a JSON-RPC 2.0 message");
				}
				this.dispatch(read.kind, message);
			}
		} catch (error) {
			this.end(error instanceof Error ? error : new Error(String(error)));
		}
	}

	/** end ends the connection with error, once: what waits fails with it. */
	end(error: Error): void {
		if (this.endError !== undefined) {
			return;
		}
		this.endError = error;
		for (const waiting of this.pending.values()) {
			waiting.reject(error);
		}
		this.pending.clear();
		for (const controller of this.handling.values()) {
			controller.abort(error);
		}
		for (const stream of this.reading.values()) {
			stream.fail(error);
		}
		for (const stream of this.writing.values()) {
			stream.halt();
		}
		if (this.pumpTimer !== undefined) {
			clearTimeout(this.pumpTimer);
		}
		this.transport.close();
		this.endDone();
	}

	// writing

	private encode(message: string): Uint8Array {
		const bytes = encoder.encode(message);
		if (bytes.length > this.messageLimit) {
			throw new Error(`a message of ${bytes.length} bytes; the limit is ${this.messageLimit}`);
		}
		return bytes;
	}

	private sendControl(message: string): void {
		this.controlQueue.push(...messageFrames(KindControl, this.encode(message)));
		this.pump();
	}

	private sendData(message: string): void {
		this.dataQueue.push(...messageFrames(KindData, this.encode(message)));
		this.pump();
	}

	/** sendStream queues a frame of a stream's bytes; no bytes end it. */
	sendStream(stream: number, payload: Uint8Array): void {
		this.streamQueue.push(frame(KindStream, stream, payload));
		this.pump();
	}

	/** sendControlInStreamOrder queues a control message behind the stream frames queued. */
	sendControlInStreamOrder(message: string): void {
		this.streamQueue.push(messageFrames(KindControl, this.encode(message)));
		this.pump();
	}

	/** next takes the next frames to send: control first, then data and streams in turn. */
	private next(): Uint8Array | Uint8Array[] | undefined {
		if (this.controlQueue.length > 0) {
			return this.controlQueue.shift();
		}
		const streamFirst = this.streamTurn || this.dataQueue.length === 0;
		this.streamTurn = !this.streamTurn;
		if (streamFirst && this.streamQueue.length > 0) {
			return this.streamQueue.shift();
		}
		if (this.dataQueue.length > 0) {
			return this.dataQueue.shift();
		}
		return this.streamQueue.shift();
	}

	/** pump hands frames to the transport while it holds less than HighWater. */
	private pump(): void {
		if (this.ended || this.pumpTimer !== undefined) {
			return;
		}
		while (this.transport.bufferedAmount < HighWater) {
			const batch: Uint8Array[] = [];
			let size = 0;
			while (size < BatchBytes) {
				const taken = this.next();
				if (taken === undefined) {
					break;
				}
				for (const piece of Array.isArray(taken) ? taken : [taken]) {
					batch.push(piece);
					size += piece.length;
				}
			}
			if (batch.length === 0) {
				return;
			}
			try {
				this.transport.send(concat(batch, size));
			} catch (error) {
				this.end(error instanceof Error ? error : new Error(String(error)));
				return;
			}
		}
		this.pumpTimer = setTimeout(() => {
			this.pumpTimer = undefined;
			this.pump();
		}, 2);
	}

	/** notify sends a control notification of the protocol. */
	notify(method: string, params: unknown): void {
		if (this.ended) {
			return;
		}
		this.sendControl(JSON.stringify({ jsonrpc: "2.0", method, params }));
	}

	/** notifyInStreamOrder sends a control notification behind the stream frames queued. */
	notifyInStreamOrder(method: string, params: unknown): void {
		if (this.ended) {
			return;
		}
		this.sendControlInStreamOrder(JSON.stringify({ jsonrpc: "2.0", method, params }));
	}

	private newCallID(): number {
		this.nextCall++;
		return 2 * this.nextCall;
	}

	/** newStreamID numbers a stream this side writes. */
	newStreamID(): number {
		this.nextStream++;
		return 2 * this.nextStream;
	}

	// calls this side makes

	/** controlCall calls a control method of the protocol. */
	async controlCall(method: string, params: unknown, options: CallOptions = {}): Promise<unknown> {
		const reply = await this.send(KindControl, method, params === undefined ? undefined : JSON.stringify(params), options, undefined, undefined);
		return reply.result;
	}

	/**
	 * call calls fn with args and decodes its result as result says; session,
	 * when given, is the session the call is in.
	 */
	async call(fn: string, args: CallArguments, result: ResultKind, options: CallOptions = {}, session?: number): Promise<unknown> {
		const scope = new Scope(this);
		let params: string | undefined;
		try {
			params = this.encodeArguments(args, scope);
		} catch (error) {
			scope.abort(false);
			throw error;
		}
		let reply: Message;
		try {
			reply = await this.send(KindData, fn, params, options, session, scope);
		} catch (error) {
			scope.abort(true);
			throw error;
		}
		return await this.decodeResult(fn, reply.result, result, scope, options);
	}

	private send(kind: number, method: string, params: string | undefined, options: CallOptions, session: number | undefined, scope: Scope | undefined): Promise<Message> {
		if (this.endError !== undefined) {
			return Promise.reject(this.endError);
		}
		if (options.signal?.aborted) {
			return Promise.reject(options.signal.reason ?? new Error("the call was cancelled"));
		}
		const id = this.newCallID();
		let text = `{"jsonrpc":"2.0","id":${id},"method":${JSON.stringify(method)}`;
		if (session !== undefined) {
			text += `,"session":${session}`;
		}
		if (params !== undefined) {
			text += `,"params":${params}`;
		}
		text += "}";
		return new Promise<Message>((resolve, reject) => {
			const onAbort = () => {
				if (this.pending.delete(id)) {
					this.notify("plugin.cancel", { id });
					reject(options.signal?.reason ?? new Error("the call was cancelled"));
				}
			};
			this.pending.set(id, {
				resolve: (message) => {
					options.signal?.removeEventListener("abort", onAbort);
					if (message.error) {
						const failure = message.error;
						reject(new RemoteError(method, failure.code, failure.message, errorCodes(failure.data)));
						return;
					}
					resolve(message);
				},
				reject: (error) => {
					options.signal?.removeEventListener("abort", onAbort);
					reject(error);
				},
			});
			options.signal?.addEventListener("abort", onAbort, { once: true });
			try {
				if (kind === KindControl) {
					this.sendControl(text);
				} else {
					this.sendData(text);
				}
			} catch (error) {
				this.pending.delete(id);
				reject(error instanceof Error ? error : new Error(String(error)));
				return;
			}
			scope?.start();
		});
	}

	/** encodeArguments encodes a call's inputs as JSON-RPC parameters. */
	private encodeArguments(args: CallArguments, scope: Scope): string | undefined {
		let streamed: unknown;
		if (args.stream !== undefined) {
			streamed = { $stream: scope.write(iteratorOf(args.stream)) };
		} else if (args.buffer !== undefined) {
			if (args.buffer.length > this.sendBuffer) {
				throw new Error(`a buffer of ${args.buffer.length} bytes; the other side takes at most ${this.sendBuffer}`);
			}
			streamed = { $buffer: { stream: scope.write(iteratorOf(args.buffer)), length: args.buffer.length } };
		}
		const hasValue = args.value !== undefined;
		if (streamed !== undefined) {
			return hasValue ? JSON.stringify([args.value, streamed]) : JSON.stringify(streamed);
		}
		if (!hasValue) {
			return undefined;
		}
		const encoded = JSON.stringify(args.value);
		if (encoded === undefined) {
			return undefined;
		}
		return encoded.startsWith("{") ? encoded : `[${encoded}]`;
	}

	/** decodeResult decodes a result as kind says, binding its stream. */
	private async decodeResult(fn: string, result: unknown, kind: ResultKind, scope: Scope, options: CallOptions): Promise<unknown> {
		switch (kind) {
			case "none":
				return undefined;
			case "value":
				return result ?? null;
			case "bytes": {
				const id = placeholder(result, "$stream");
				if (id === undefined) {
					throw new Error(`${fn}: the result is not a stream`);
				}
				return byteStream(this.claim(id), options.signal);
			}
			case "buffer": {
				const buffer = (result as { $buffer?: { stream?: number; length?: number; region?: string } } | null)?.$buffer;
				if (!buffer || buffer.region !== undefined || typeof buffer.stream !== "number" || typeof buffer.length !== "number") {
					throw new Error(`${fn}: the result is not a buffer of bytes`);
				}
				return await this.claim(buffer.stream).readExactly(buffer.length, this.options.limits.buffer ?? DefaultBufferLimit);
			}
			case "items": {
				const id = placeholder(result, "$items");
				if (id === undefined) {
					throw new Error(`${fn}: the result is not a typed stream`);
				}
				return itemsOf(this.claim(id), options.signal);
			}
		}
		void scope;
	}

	// sessions this side opens

	/** open opens a session of api on the other side. */
	async open(api: string, params: unknown, options: CallOptions = {}): Promise<Session> {
		this.nextSession++;
		const id = 2 * this.nextSession;
		const encoded = params === undefined ? undefined : JSON.stringify(params);
		const wrapped = encoded === undefined ? undefined : encoded.startsWith("{") ? encoded : `[${encoded}]`;
		try {
			await this.send(KindData, `${api}.$open`, wrapped, options, id, undefined);
		} catch (error) {
			if (options.signal?.aborted) {
				// It may have been made after all: closed, whichever way it went.
				this.send(KindData, `${api}.$close`, undefined, {}, id, undefined).catch(() => {});
			}
			throw error;
		}
		return new PeerSession(this, api, id);
	}

	// what the other side sends

	private dispatch(kind: number, message: Message): void {
		if (message.method === undefined || message.method === "") {
			if (typeof message.id !== "number" || (message.result === undefined && message.error === undefined)) {
				throw new ProtocolError("a message without method, id or result");
			}
			const waiting = this.pending.get(message.id);
			if (waiting !== undefined) {
				this.pending.delete(message.id);
				waiting.resolve(message);
			}
			return;
		}
		const protocolMethod = message.method.startsWith("plugin.");
		if ((kind === KindControl) !== protocolMethod) {
			throw new ProtocolError(`${message.method} on the wrong channel`);
		}
		if (kind === KindControl) {
			this.dispatchControl(message);
			return;
		}
		if (message.id === undefined) {
			this.takeEvent(message.method, message.params);
			return;
		}
		this.answerCall(message);
	}

	private dispatchControl(message: Message): void {
		const params = (message.params ?? {}) as Record<string, unknown>;
		switch (message.method) {
			case "plugin.ping":
				if (typeof message.id === "number") {
					this.answer(KindControl, message.id, {}, undefined);
				}
				return;
			case "plugin.cancel":
				this.handling.get(Number(params.id))?.abort(new Error("the call was cancelled"));
				return;
			case "plugin.window": {
				const bytes = Number(params.bytes);
				if (!(bytes > 0)) {
					throw new ProtocolError("a broken window grant");
				}
				this.writing.get(Number(params.stream))?.grant(bytes);
				return;
			}
			case "plugin.reset": {
				const id = Number(params.stream);
				const reason = String(params.reason ?? "");
				this.writing.get(id)?.halt();
				const reader = this.reading.get(id);
				if (reader !== undefined) {
					if (reader.claimed) {
						this.reading.delete(id);
					}
					reader.fail(new RemoteError("", Codes.failed, "the stream failed on the other side: " + reason, errorCodes({ errors: params.errors })));
				}
				return;
			}
			case "plugin.release":
			case "plugin.unmap":
				return; // shared memory is not offered to a client
		}
		const id = message.id;
		Promise.resolve()
			.then(() => this.options.control(message.method as string, message.params))
			.then(
				(result) => typeof id === "number" && this.answer(KindControl, id, result ?? null, undefined),
				(error: unknown) => {
					if (typeof id === "number") {
						this.answer(KindControl, id, undefined, { code: Codes.failed, message: errorMessage(error) });
					} else {
						this.options.report(`${message.method}: ${errorMessage(error)}`);
					}
				},
			);
	}

	private takeEvent(name: string, payload: unknown): void {
		if (!this.options.events.has(name)) {
			return; // nobody here takes it
		}
		if (this.events.length >= this.options.eventQueue) {
			this.options.report(`event ${name} dropped: ${this.options.eventQueue} events wait already`);
			return;
		}
		this.events.push({ name, payload: unwrapParams(payload) });
		if (!this.delivering) {
			this.delivering = true;
			void this.deliver();
		}
	}

	/** deliver gives the events to their handlers, one at a time, in order. */
	private async deliver(): Promise<void> {
		while (this.events.length > 0 && !this.ended) {
			const event = this.events.shift()!;
			await this.handleEvent(event.name, event.payload);
		}
		this.delivering = false;
	}

	/**
	 * handleEvent gives an event to its handler in its turn, reporting its
	 * failure: the handlers of events and of kept events (handleKept) run one
	 * at a time.
	 */
	async handleEvent(name: string, payload: unknown): Promise<void> {
		const failure = await this.runHandler(name, payload, undefined);
		if (failure !== undefined) {
			this.options.report(`event ${name}: ${errorMessage(failure.error)}`);
		}
	}

	/**
	 * handleKept gives a kept event to its handler in its turn, its cursor
	 * after the payload, and returns the refusal of a handler that may refuse
	 * it (ConnectOptions.kept): its failure, the event to be had again.
	 * Another handler's failure is reported, as an event's, and the event is
	 * had.
	 */
	async handleKept(name: string, payload: unknown, cursor: Cursor): Promise<{ error: unknown } | undefined> {
		const failure = await this.runHandler(name, payload, cursor);
		if (failure === undefined || this.options.refusing?.has(name)) {
			return failure;
		}
		this.options.report(`event ${name}: ${errorMessage(failure.error)}`);
		return undefined;
	}

	/**
	 * handleState gives a state to its handler (ConnectOptions.states) in its
	 * turn, with its revision and whether it was deleted, reporting its
	 * failure: the handlers of states, events and kept events run one at a
	 * time.
	 */
	async handleState(name: string, handler: (value: unknown, revision?: number, deleted?: boolean) => unknown,
		value: unknown, revision: number, deleted: boolean): Promise<void> {
		const run = this.turn.then(async (): Promise<unknown> => {
			try {
				await handler(value, revision, deleted);
				return undefined;
			} catch (error) {
				return error ?? new Error("the handler failed");
			}
		});
		this.turn = run.then(() => {});
		const failure = await run;
		if (failure !== undefined) {
			this.options.report(`state ${name}: ${errorMessage(failure)}`);
		}
	}

	/** runHandler runs an event's handler in its turn, and returns its failure: what it threw, or its promise rejected with. */
	private runHandler(name: string, payload: unknown, cursor: Cursor | undefined): Promise<{ error: unknown } | undefined> {
		const handler = this.options.events.get(name);
		if (handler === undefined) {
			return Promise.resolve(undefined);
		}
		const run = this.turn.then(async (): Promise<{ error: unknown } | undefined> => {
			try {
				await (cursor === undefined ? handler(payload) : handler(payload, cursor));
				return undefined;
			} catch (error) {
				return { error };
			}
		});
		this.turn = run.then(() => {});
		return run;
	}

	/** publish sends an event; false when too many wait to be sent. */
	publish(event: string, payload: unknown): boolean {
		if (this.endError !== undefined) {
			throw this.endError;
		}
		if (this.dataQueue.length >= this.options.eventQueue * 4) {
			return false;
		}
		const encoded = payload === undefined ? undefined : JSON.stringify(payload);
		const params = encoded === undefined ? "" : `,"params":${encoded.startsWith("{") ? encoded : `[${encoded}]`}`;
		this.sendData(`{"jsonrpc":"2.0","method":${JSON.stringify(event)}${params}}`);
		return true;
	}

	/** answerCall runs a call to a function this side offers, and answers it. */
	private answerCall(message: Message): void {
		const id = message.id as number;
		const method = message.method as string;
		if (!this.ready) {
			this.answer(KindData, id, undefined, { code: Codes.notReady, message: "called before the handshake ended" });
			return;
		}
		if (message.session !== undefined) {
			this.answer(KindData, id, undefined, { code: Codes.noSession, message: "this client serves no sessions" });
			return;
		}
		const implemented = this.functions.get(method);
		if (implemented === undefined) {
			this.answer(KindData, id, undefined, { code: Codes.noFunction, message: "no function " + method });
			return;
		}
		const controller = new AbortController();
		this.handling.set(id, controller);
		const scope = new Scope(this);
		const finish = () => {
			scope.abandonReads();
			this.handling.delete(id);
		};
		let input: unknown;
		let streamed: unknown;
		try {
			[input, streamed] = this.decodeParams(implemented, message.params, scope, controller.signal);
		} catch (error) {
			finish();
			this.answer(KindData, id, undefined, { code: Codes.invalidParams, message: "invalid parameters: " + errorMessage(error) });
			return;
		}
		Promise.resolve()
			.then(() => implemented.call(input, streamed, { signal: controller.signal }))
			.then(async (result) => {
				let encoded: unknown;
				try {
					encoded = this.encodeResult(implemented.result, await result, scope);
				} catch (error) {
					scope.abort(false);
					throw error;
				}
				this.answer(KindData, id, encoded ?? null, undefined);
				scope.start();
				await scope.finished();
				finish();
			})
			.catch((error: unknown) => {
				scope.abort(false);
				finish();
				const cancelled = controller.signal.aborted;
				const codes = codesOf(error);
				this.answer(KindData, id, undefined, {
					code: cancelled ? Codes.cancelled : Codes.failed,
					message: errorMessage(error),
					data: codes.length > 0 ? { errors: codes } : undefined,
				});
			});
	}

	/** decodeParams decodes a call's parameters into its value and its stream or buffer. */
	private decodeParams(implemented: FunctionImplementation, params: unknown, scope: Scope, signal: AbortSignal): [unknown, unknown] {
		const values = implemented.input && implemented.stream ? params : undefined;
		if (implemented.input && implemented.stream) {
			if (!Array.isArray(values) || values.length !== 2) {
				throw new Error("two values are expected");
			}
			return [values[0], this.decodeStreamed(implemented.stream, values[1], scope, signal)];
		}
		if (implemented.stream) {
			const single = Array.isArray(params) && params.length === 1 ? params[0] : params;
			return [undefined, this.decodeStreamed(implemented.stream, single, scope, signal)];
		}
		if (implemented.input) {
			return [unwrapParams(params), undefined];
		}
		return [undefined, undefined];
	}

	private decodeStreamed(kind: "bytes" | "buffer", value: unknown, scope: Scope, signal: AbortSignal): unknown {
		if (kind === "bytes") {
			const id = placeholder(value, "$stream");
			if (id === undefined) {
				throw new Error("not a stream");
			}
			return byteStream(scope.read(id), signal);
		}
		const buffer = (value as { $buffer?: { stream?: number; length?: number } } | null)?.$buffer;
		if (!buffer || typeof buffer.stream !== "number" || typeof buffer.length !== "number") {
			throw new Error("not a buffer of bytes");
		}
		return scope.read(buffer.stream).readExactly(buffer.length, this.options.limits.buffer ?? DefaultBufferLimit);
	}

	/** encodeResult encodes what a function returned, its stream started once answered. */
	private encodeResult(kind: ResultKind, result: unknown, scope: Scope): unknown {
		switch (kind) {
			case "none":
				return null;
			case "value":
				return result;
			case "bytes":
				return { $stream: scope.write(iteratorOf(result as ByteSource)) };
			case "buffer": {
				const bytes = result as Uint8Array;
				if (bytes.length > this.sendBuffer) {
					throw new Error(`a buffer of ${bytes.length} bytes; the other side takes at most ${this.sendBuffer}`);
				}
				return { $buffer: { stream: scope.write(iteratorOf(bytes)), length: bytes.length } };
			}
			case "items":
				return { $items: scope.write(itemLines(result as AsyncIterable<unknown>)) };
		}
	}

	private answer(kind: number, id: number, result: unknown, failure: { code: number; message: string; data?: unknown } | undefined): void {
		if (this.ended) {
			return;
		}
		let text: string;
		if (failure !== undefined) {
			text = JSON.stringify({ jsonrpc: "2.0", id, error: failure });
		} else {
			const encoded = JSON.stringify(result ?? null);
			text = `{"jsonrpc":"2.0","id":${id},"result":${encoded}}`;
		}
		try {
			if (kind === KindControl) {
				this.sendControl(text);
			} else {
				this.sendData(text);
			}
		} catch (error) {
			const fallback = JSON.stringify({ jsonrpc: "2.0", id, error: { code: Codes.internal, message: "the answer is too large: " + errorMessage(error) } });
			kind === KindControl ? this.sendControl(fallback) : this.sendData(fallback);
		}
	}

	// streams

	/** incoming returns the stream the other side writes under id, made at its first frame or mention. */
	private incoming(id: number): Incoming {
		if (id === 0 || id % 2 === 0) {
			throw new ProtocolError(`stream ${id} is not the other side's to write`);
		}
		let stream = this.reading.get(id);
		if (stream === undefined) {
			if (this.reading.size >= MaxStreams) {
				throw new ProtocolError(`more than ${MaxStreams} streams at once`);
			}
			stream = new Incoming(this, id, this.options.limits.window ?? DefaultStreamWindow);
			this.reading.set(id, stream);
		}
		return stream;
	}

	/** claim returns a stream a call's placeholder names; its frames may have come first. */
	claim(id: number): Incoming {
		const stream = this.incoming(id);
		if (stream.claimed) {
			throw new Error(`stream ${id} is named twice`);
		}
		stream.claimed = true;
		if (stream.ended || stream.failure !== undefined) {
			this.reading.delete(id);
		}
		return stream;
	}

	forgetIncoming(id: number, stream: Incoming): void {
		if (this.reading.get(id) === stream) {
			this.reading.delete(id);
		}
	}

	private streamFrame(id: number, payload: Uint8Array): void {
		const stream = this.incoming(id);
		stream.push(payload);
		if (payload.length === 0 && stream.claimed) {
			this.reading.delete(id);
		}
	}

	registerOutgoing(stream: Outgoing): void {
		this.writing.set(stream.id, stream);
	}

	forgetOutgoing(id: number): void {
		this.writing.delete(id);
	}
}

/** errorCodes reads the codes of an error's data; none for data of another shape. */
function errorCodes(data: unknown): string[] {
	const errors = (data as { errors?: unknown } | null | undefined)?.errors;
	return Array.isArray(errors) ? errors.filter((code): code is string => typeof code === "string") : [];
}

function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

/** unwrapParams returns a value from JSON-RPC parameters: itself an object, or in an array of one. */
export function unwrapParams(params: unknown): unknown {
	return Array.isArray(params) && params.length === 1 ? params[0] : params;
}

function placeholder(value: unknown, key: "$stream" | "$items"): number | undefined {
	const id = (value as Record<string, unknown> | null)?.[key];
	return typeof id === "number" && id > 0 ? id : undefined;
}

/** Incoming is a stream this side reads, granting its writer more as it reads. */
export class Incoming {
	private readonly peer: Peer;
	readonly id: number;
	private readonly window: number;
	private chunks: Uint8Array[] = [];
	private held = 0;
	private consumed = 0;
	ended = false;
	failure: Error | undefined;
	private closed = false;
	claimed = false;
	private wake: (() => void) | undefined;

	constructor(peer: Peer, id: number, window: number) {
		this.peer = peer;
		this.id = id;
		this.window = window;
	}

	push(payload: Uint8Array): void {
		if (payload.length === 0) {
			this.ended = true;
		} else if (this.closed) {
			return; // abandoned: its writer stops once it hears so
		} else if (this.held + payload.length > this.window) {
			throw new ProtocolError(`stream ${this.id} overran its window`);
		} else {
			this.chunks.push(payload);
			this.held += payload.length;
		}
		this.signal();
	}

	fail(error: Error): void {
		if (this.failure === undefined && !this.ended) {
			this.failure = error;
		}
		this.signal();
	}

	private signal(): void {
		const wake = this.wake;
		this.wake = undefined;
		wake?.();
	}

	/** next returns the next bytes, or null at the stream's end. */
	async next(): Promise<Uint8Array | null> {
		for (;;) {
			if (this.chunks.length > 0) {
				const chunk = this.chunks.shift()!;
				this.held -= chunk.length;
				this.consumed += chunk.length;
				if (this.consumed >= this.window / 2 && !this.ended) {
					this.peer.notify("plugin.window", { stream: this.id, bytes: this.consumed });
					this.consumed = 0;
				}
				return chunk;
			}
			if (this.closed) {
				throw new Error("the stream was closed by its reader");
			}
			if (this.failure !== undefined) {
				throw this.failure;
			}
			if (this.ended) {
				return null;
			}
			await new Promise<void>((resolve) => (this.wake = resolve));
		}
	}

	/** close abandons the stream when it has not ended: its writer is told to stop. */
	close(reason = "the reader closed the stream"): void {
		if (this.closed) {
			return;
		}
		this.closed = true;
		const finished = this.ended || this.failure !== undefined;
		this.chunks = [];
		this.held = 0;
		this.signal();
		this.peer.forgetIncoming(this.id, this);
		if (!finished) {
			this.peer.notify("plugin.reset", { stream: this.id, reason });
		}
	}

	/** readExactly reads exactly length bytes and the stream's end: a buffer. */
	async readExactly(length: number, limit: number): Promise<Uint8Array> {
		if (length < 0 || length > limit) {
			this.close();
			throw new Error(`a buffer of ${length} bytes; this side takes at most ${limit}`);
		}
		const data = new Uint8Array(length);
		let done = 0;
		for (;;) {
			const chunk = await this.next();
			if (chunk === null) {
				break;
			}
			if (done + chunk.length > length) {
				this.close();
				throw new Error(`a buffer longer than its ${length} bytes`);
			}
			data.set(chunk, done);
			done += chunk.length;
		}
		if (done !== length) {
			throw new Error(`a buffer of ${length} bytes ended after ${done}`);
		}
		return data;
	}
}

/** byteStream is an incoming stream as a ByteStream; signal abandons it. */
function byteStream(stream: Incoming, signal?: AbortSignal): ByteStream {
	signal?.addEventListener("abort", () => stream.close("the call was cancelled"), { once: true });
	const iterator: AsyncIterator<Uint8Array> = {
		next: async () => {
			const chunk = await stream.next();
			return chunk === null ? { value: undefined, done: true } : { value: chunk, done: false };
		},
		return: async () => {
			stream.close();
			return { value: undefined, done: true };
		},
	};
	return {
		[Symbol.asyncIterator]: () => iterator,
		readAll: async () => {
			const pieces: Uint8Array[] = [];
			let size = 0;
			for (;;) {
				const chunk = await stream.next();
				if (chunk === null) {
					return concat(pieces, size);
				}
				pieces.push(chunk);
				size += chunk.length;
			}
		},
		cancel: (reason?: string) => stream.close(reason),
	};
}

/** itemsOf is a typed stream's items: one JSON value a line, the last {"$error": ...} when it failed. */
function itemsOf(stream: Incoming, signal?: AbortSignal): AsyncIterable<unknown> {
	signal?.addEventListener("abort", () => stream.close("the call was cancelled"), { once: true });
	let rest = "";
	const lines: string[] = [];
	const streaming = new TextDecoder();
	let finished = false;
	const iterator: AsyncIterator<unknown> = {
		next: async () => {
			for (;;) {
				const line = lines.shift();
				if (line !== undefined) {
					if (line.trim() === "") {
						continue;
					}
					const item = JSON.parse(line) as unknown;
					const failure = item as { $error?: unknown; $errors?: unknown } | null;
					if (failure !== null && typeof failure === "object" && !Array.isArray(failure) && typeof failure.$error === "string") {
						finished = true;
						stream.close();
						throw new RemoteError("", Codes.failed, failure.$error, errorCodes({ errors: failure.$errors }));
					}
					return { value: item, done: false };
				}
				if (finished) {
					return { value: undefined, done: true };
				}
				const chunk = await stream.next();
				if (chunk === null) {
					finished = true;
					rest += streaming.decode();
					if (rest !== "") {
						lines.push(rest);
						rest = "";
					}
					continue;
				}
				const text = rest + streaming.decode(chunk, { stream: true });
				const parts = text.split("\n");
				rest = parts.pop() ?? "";
				lines.push(...parts);
			}
		},
		return: async () => {
			finished = true;
			stream.close();
			return { value: undefined, done: true };
		},
	};
	return { [Symbol.asyncIterator]: () => iterator };
}

/** iteratorOf reads a ByteSource in pieces. */
function iteratorOf(source: ByteSource): AsyncIterator<Uint8Array> {
	if (source instanceof Uint8Array) {
		let given = false;
		return {
			next: async () => {
				if (given) {
					return { value: undefined, done: true };
				}
				given = true;
				return { value: source, done: false };
			},
		};
	}
	if (typeof (source as ReadableStream<Uint8Array>).getReader === "function" && !(Symbol.asyncIterator in source)) {
		const reader = (source as ReadableStream<Uint8Array>).getReader();
		return {
			next: async () => {
				const read = await reader.read();
				return read.done ? { value: undefined, done: true } : { value: read.value, done: false };
			},
			return: async () => {
				await reader.cancel();
				return { value: undefined, done: true };
			},
		};
	}
	return (source as AsyncIterable<Uint8Array>)[Symbol.asyncIterator]();
}

/** itemLines writes a typed stream's items as lines of JSON. */
async function* itemLines(items: AsyncIterable<unknown>): AsyncGenerator<Uint8Array> {
	try {
		for await (const item of items) {
			yield encoder.encode(JSON.stringify(item) + "\n");
		}
	} catch (error) {
		const codes = codesOf(error);
		yield encoder.encode(JSON.stringify(codes.length > 0 ? { $error: errorMessage(error), $errors: codes } : { $error: errorMessage(error) }) + "\n");
	}
}

/** Outgoing is a stream this side writes, within the window the reader grants. */
export class Outgoing {
	private readonly peer: Peer;
	readonly id: number;
	private readonly source: AsyncIterator<Uint8Array>;
	private credit: number;
	private halted = false;
	private wake: (() => void) | undefined;
	readonly finished: Promise<void>;
	private finish!: () => void;

	constructor(peer: Peer, source: AsyncIterator<Uint8Array>) {
		this.peer = peer;
		this.id = peer.newStreamID();
		this.source = source;
		this.credit = peer.sendWindow;
		this.finished = new Promise((resolve) => (this.finish = resolve));
		peer.registerOutgoing(this);
	}

	grant(bytes: number): void {
		this.credit += bytes;
		this.signal();
	}

	/** halt stops the stream: its reader abandoned it, or the call ended. */
	halt(): void {
		if (this.halted) {
			return;
		}
		this.halted = true;
		this.signal();
		void this.source.return?.();
	}

	private signal(): void {
		const wake = this.wake;
		this.wake = undefined;
		wake?.();
	}

	private end(): void {
		this.peer.sendStream(this.id, new Uint8Array(0));
	}

	/** run sends the source's bytes within the window, then the end. */
	async run(): Promise<void> {
		try {
			for (;;) {
				if (this.halted) {
					this.end();
					return;
				}
				const read = await this.source.next();
				if (read.done) {
					this.end();
					return;
				}
				const chunk = read.value;
				for (let offset = 0; offset < chunk.length;) {
					while (this.credit <= 0 && !this.halted && !this.peer.ended) {
						await new Promise<void>((resolve) => (this.wake = resolve));
					}
					if (this.peer.ended) {
						return;
					}
					if (this.halted) {
						this.end();
						return;
					}
					const n = Math.min(MaxPiece, this.credit, chunk.length - offset);
					this.peer.sendStream(this.id, chunk.slice(offset, offset + n));
					this.credit -= n;
					offset += n;
				}
			}
		} catch (error) {
			if (this.halted) {
				this.end();
				return;
			}
			const codes = codesOf(error);
			this.peer.notifyInStreamOrder("plugin.reset", codes.length > 0
				? { stream: this.id, reason: errorMessage(error), errors: codes }
				: { stream: this.id, reason: errorMessage(error) });
		} finally {
			this.peer.forgetOutgoing(this.id);
			this.finish();
		}
	}
}

/** Scope holds the streams of one call: those it writes and those it reads. */
class Scope {
	private readonly peer: Peer;
	private readonly writes: Outgoing[] = [];
	private readonly reads: Incoming[] = [];

	constructor(peer: Peer) {
		this.peer = peer;
	}

	write(source: AsyncIterator<Uint8Array>): number {
		const stream = new Outgoing(this.peer, source);
		this.writes.push(stream);
		return stream.id;
	}

	read(id: number): Incoming {
		const stream = this.peer.claim(id);
		this.reads.push(stream);
		return stream;
	}

	/** start sends the streams written, once the message naming them is queued. */
	start(): void {
		for (const stream of this.writes) {
			void stream.run();
		}
	}

	async finished(): Promise<void> {
		await Promise.all(this.writes.map((stream) => stream.finished));
	}

	/** abort stops the streams written and abandons those read. */
	abort(started: boolean): void {
		for (const stream of this.writes) {
			if (started) {
				stream.halt();
			} else {
				this.peer.forgetOutgoing(stream.id);
			}
		}
		this.abandonReads();
	}

	abandonReads(): void {
		for (const stream of this.reads) {
			stream.close();
		}
	}
}

/** PeerSession is a session this side opened. */
class PeerSession implements Session {
	private readonly peer: Peer;
	readonly api: string;
	readonly id: number;
	private closing = false;
	private ended = false;
	readonly done: Promise<void>;
	private endSession!: () => void;

	constructor(peer: Peer, api: string, id: number) {
		this.peer = peer;
		this.api = api;
		this.id = id;
		this.done = new Promise((resolve) => (this.endSession = resolve));
		void peer.done.then(() => this.finish());
	}

	private finish(): void {
		if (!this.ended) {
			this.ended = true;
			this.endSession();
		}
	}

	use(): void {}

	call(fn: string, args: CallArguments, result: ResultKind, options?: CallOptions): Promise<unknown> {
		if (this.ended) {
			return Promise.reject(new NoSessionError(fn));
		}
		if (fn.slice(0, fn.lastIndexOf(".")) !== this.api) {
			return Promise.reject(new Error(`${fn}: not a function of the session's API, ${this.api}`));
		}
		return this.peer.call(fn, args, result, options, this.id);
	}

	async close(options?: CallOptions): Promise<void> {
		if (this.closing) {
			return;
		}
		this.closing = true;
		this.finish();
		if (this.peer.ended) {
			return;
		}
		await this.peer.call(`${this.api}.$close`, {}, "none", options, this.id);
	}
}
