// The errors a client meets.

/** The protocol's error codes; negative ones are JSON-RPC's. */
export const Codes = {
	parse: -32700,
	invalidRequest: -32600,
	noFunction: -32601,
	invalidParams: -32602,
	internal: -32603,
	failed: 1,
	panicked: 2,
	cancelled: 3,
	notReady: 4,
	noSession: 5,
} as const;

/**
 * RemoteError is an error the other side answered a call with, or the
 * failure of a stream it wrote (then without a function). errors are the
 * codes of the declared errors its error matched ("io/fs.ErrNotExist",
 * "goframework.io/vfs.ErrNotEmpty"): is(code) tests one, as Go's errors.Is.
 */
export class RemoteError extends Error {
	readonly function: string;
	readonly code: number;
	readonly errors: readonly string[];

	constructor(fn: string, code: number, message: string, errors: readonly string[] = []) {
		super(fn ? `${fn}: ${message}` : message);
		this.name = "RemoteError";
		this.function = fn;
		this.code = code;
		this.errors = errors;
	}

	/** is reports whether the error is the one declared under code. */
	is(code: string): boolean {
		return this.errors.includes(code);
	}
}

/**
 * CodedError is an error a function the client offers fails with, carrying
 * the codes of the declared errors it is, so that the other side matches
 * them (Go's errors.Is): new CodedError("open x: no such file", ["io/fs.ErrNotExist"]).
 */
export class CodedError extends Error {
	readonly errors: readonly string[];

	constructor(message: string, errors: readonly string[]) {
		super(message);
		this.name = "CodedError";
		this.errors = errors;
	}
}

/** NotConnectedError reports a call while the client has no connection. */
export class NotConnectedError extends Error {
	constructor(what: string) {
		super(`${what}: the client is not connected to its application`);
		this.name = "NotConnectedError";
	}
}

/** RefusedError reports a connection the application refused: a wrong token. */
export class RefusedError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "RefusedError";
	}
}

/** NoSessionError reports a call in a session that ended. */
export class NoSessionError extends Error {
	constructor(what: string) {
		super(`${what}: the session is not open`);
		this.name = "NoSessionError";
	}
}

/** codesOf returns the declared errors' codes an error thrown by a function carries. */
export function codesOf(error: unknown): readonly string[] {
	if (error instanceof CodedError || error instanceof RemoteError) {
		return error.errors;
	}
	return [];
}
